{"cards": [{"node_code": "N_f7001337dea8a08c", "definition": "指航道整治中清除河床表面松散覆盖物（如淤泥、细沙、植被）以露出河床基面或改善水流条件的工程措施。", "boundary": "本节点特指“清面”这一具体整治手段，即对河床表面进行清理。边界在于区分“清面”与“疏浚”（疏浚侧重挖掘深层泥沙以增加水深，清面侧重表层清理）、“整治建筑物”（清面通常不依赖大型固定建筑物，而是通过清理改变局部流态）。若内容涉及大规模挖泥，归入疏浚工程。", "includes": ["河床表层淤泥、细沙及植被的清除技术", "清面对局部水流形态及航道稳定性的影响分析", "清面作业的施工工艺与适用条件"], "excludes": ["深层泥沙挖掘与疏浚作业", "大型整治建筑物（如丁坝、顺坝）的建设"], "sibling_distinctions": [{"other_code": "N_85b55cbf9ebb2fb6", "rule": "石滩、浅滩整治侧重通过工程措施改变滩体形态或水流；清面侧重清除表层松散物质，常作为浅滩整治的辅助或独立手段。"}, {"other_code": "N_ff3cba54fc2adf1f", "rule": "整治建筑物侧重丁坝、顺坝等固定结构的设计与功能；清面侧重对河床表面的清理操作，通常不涉及大型结构物。"}], "cross_boundary_rule": "若清面作业伴随大规模疏浚，且以挖泥为主，主挂载疏浚工程；若仅为表层清理以改善流态，主挂载本节点。"}, {"node_code": "N_41cd2580fc73534e", "definition": "研究航道整治中用于保护河岸、河床免受冲刷破坏的护岸与护坡工程技术，涵盖结构形式、材料选择及稳定性分析。", "boundary": "本节点聚焦于“护岸”与“护坡”工程，旨在保护航道边界稳定。边界在于区分“护岸护坡”与“整治建筑物”（如丁坝，侧重导流）、“疏浚”（侧重挖泥）。若内容涉及护岸结构的设计、施工及抗冲性能，主挂载本节点。", "includes": ["航道整治护岸结构（如抛石、砌石、混凝土护坡）设计", "护坡工程材料及抗冲刷性能研究", "护岸护坡工程的施工技术与稳定性分析"], "excludes": ["丁坝、顺坝等导流型整治建筑物的设计", "单纯的航道疏浚挖泥作业"], "sibling_distinctions": [{"other_code": "N_ff3cba54fc2adf1f", "rule": "护岸与护坡侧重保护河岸河床免受冲刷；整治建筑物（如丁坝）侧重通过挑流、束水改变水流形态以稳定航道。"}, {"other_code": "N_85b55cbf9ebb2fb6", "rule": "石滩、浅滩整治侧重整体滩体形态调整；护岸护坡侧重局部岸坡保护，常作为浅滩整治的组成部分。"}], "cross_boundary_rule": "若护岸工程与丁坝等整治建筑物结合使用，侧重护岸结构本身归入本节点；侧重整体导流方案归入整治建筑物。"}, {"node_code": "N_ff3cba54fc2adf1f", "definition": "研究用于改变水流形态、稳定航道线形的固定工程结构（如丁坝、顺坝、潜坝等）的设计、功能及水流效应。", "boundary": "本节点聚焦于“整治建筑物”本身，即通过物理结构干预水流。边界在于区分“整治建筑物”与“护岸护坡”（侧重保护）、“清面”（侧重清理）。若内容涉及丁坝、顺坝的布置、设计原理及水流动力学效应，主挂载本节点。", "includes": ["丁坝、顺坝、潜坝等整治建筑物的设计与布置", "整治建筑物对水流形态、泥沙运动的影响分析", "整治建筑物的结构安全与耐久性研究"], "excludes": ["单纯的护岸护坡工程（归入航道整治护岸与护坡）", "河床表层清理作业（归入清面）"], "sibling_distinctions": [{"other_code": "N_41cd2580fc73534e", "rule": "整治建筑物侧重通过结构导流、束水；护岸护坡侧重保护岸坡免受冲刷，两者功能不同但常配合使用。"}, {"other_code": "N_f7001337dea8a08c", "rule": "整治建筑物为固定结构；清面为对河床表面的清理操作，无固定结构物。"}], "cross_boundary_rule": "若内容涉及整治建筑物的施工方法，主挂载航道工程施工；若涉及设计原理与水流效应，主挂载本节点。"}]}
